-- Replaces the stale (~23-month-old) seed data with a freshly web-sourced batch.
-- Old rows are deactivated (active=false), not deleted, to preserve any history/FKs.
UPDATE jobs SET active = false WHERE active = true;

INSERT INTO jobs (
    company, role, description, location, employment_type, experience_level,
    salary_range, source_url, minimum_readiness_score, required_skills,
    nice_to_have_skills, application_deadline, active
) VALUES
('Tata Consultancy Services (TCS)', 'Systems Engineer', 'Join TCS through the National Qualifier Test (NQT) for entry-level engineering roles across software development, testing, cloud, and infrastructure. Selected candidates undergo structured training before project deployment across TCS''s global delivery centres. Roles span Java, Python, and full-stack tracks under the TCS Ninja and TCS Digital bands.', 'PAN India', 'FULL_TIME', 'FRESHER', '3.6-7 LPA', 'https://nextstep.tcs.com/campus/', 40, '["Java","SQL","Data Structures & Algorithms","Aptitude","OOP"]'::jsonb, '["Python","Cloud Basics","Git"]'::jsonb, '2026-08-30', true),
('Tata Consultancy Services (TCS)', 'Software Engineer – TCS Digital', 'TCS Digital track targets candidates with advanced coding skills for higher-complexity projects in cloud, AI, and enterprise software. Shortlisted candidates appear for an Advanced Qualifier Test followed by technical and HR interviews. Starting CTC is significantly higher than the Ninja band and involves faster project placement.', 'Bengaluru, Hyderabad, Pune, Chennai, India', 'FULL_TIME', 'FRESHER', '7-11.5 LPA', 'https://nextstep.tcs.com/campus/', 55, '["Java","Python","DSA","System Design Basics","SQL"]'::jsonb, '["AWS","Docker","React"]'::jsonb, '2026-08-30', true),
('Infosys', 'Systems Engineer (Trainee)', 'Infosys recruits freshers through the InfyTQ platform and off-campus drives for the Systems Engineer role, which comes with 16–22 weeks of training at the Mysore Global Education Centre before project deployment. The role involves full-stack development, testing, and digital transformation projects across banking, retail, and insurance verticals. Candidates should have cleared InfyTQ foundation certifications for a stronger application.', 'Bengaluru, Mysore, Pune, India', 'FULL_TIME', 'FRESHER', '3.6-4.5 LPA', 'https://www.infosys.com/careers/apply.html', 40, '["Java","SQL","OOP","Problem Solving","Communication"]'::jsonb, '["Python","JavaScript","InfyTQ Certification"]'::jsonb, '2026-08-25', true),
('Infosys', 'Digital Specialist Engineer (Trainee)', 'Infosys''s Digital Specialist Engineer track requires demonstrated competency in advanced Java, Python, or full-stack frameworks and is verified via the InfyTQ Power Programmer certification. Selected candidates receive a higher starting package plus a joining bonus and are deployed faster onto client projects requiring cloud and AI skills. The selection involves InfyTQ certification, a technical assessment, and two interview rounds.', 'Bengaluru, Hyderabad, Pune, Chennai, India', 'FULL_TIME', 'FRESHER', '6.25-9 LPA', 'https://www.infosys.com/careers/apply.html', 55, '["Advanced Java or Python","Frameworks (Spring/Django)","SQL","REST APIs","DSA"]'::jsonb, '["Cloud (AWS/Azure)","Microservices","Docker"]'::jsonb, '2026-08-25', true),
('Wipro', 'Project Engineer (Elite NLTH)', 'Wipro Elite National Talent Hunt (NLTH) is the flagship off-campus fresher hiring program with three stages: an online aptitude and coding assessment, a technical interview, and an HR round. Selected candidates join as Project Engineers and are deployed on client-facing development and testing projects after a brief training period. The program accepts 2024 and 2025 engineering graduates across all disciplines.', 'Hybrid – Bengaluru, Hyderabad, Chennai, Pune, India', 'FULL_TIME', 'FRESHER', '3.5 LPA', 'https://careers.wipro.com/', 40, '["JavaScript","SQL","Communication","Logical Reasoning","Basic OOP"]'::jsonb, '["Python","Git","Linux Basics"]'::jsonb, '2026-09-05', true),
('Wipro', 'Software Engineer (Elite WILP)', 'Wipro''s Elite program for experienced lateral hires with up to two years of prior software development experience, focusing on Java, Python, and cloud-native application development. Engineers join active delivery teams and work on digital transformation, testing, and cloud migration engagements for global clients. Three rounds of interviews include a coding test, technical round, and HR discussion.', 'Bengaluru, Hyderabad, Chennai, India', 'FULL_TIME', 'JUNIOR', '4.5-7 LPA', 'https://careers.wipro.com/', 55, '["Java or Python","SQL","REST APIs","Git","Agile"]'::jsonb, '["Spring Boot","Docker","AWS"]'::jsonb, NULL, true),
('Accenture', 'Associate Software Engineer', 'Accenture India''s large-scale fresher hiring for the Associate Software Engineer (ASE) role covers digital transformation, application development, cloud engineering, and testing tracks. Candidates are assessed through Accenture''s iAMPLIFY online test covering cognitive, technical, and communication skills before two interview rounds. Successful candidates join Accenture''s entry-level engineering pool and are staffed to client accounts across BFSI, retail, and manufacturing verticals.', 'Bengaluru, Chennai, Hyderabad, Pune, Gurgaon, Mumbai, India', 'FULL_TIME', 'FRESHER', '4.5-6.5 LPA', 'https://indiacampus.accenture.com/', 40, '["Java","SQL","Cloud Basics","Communication","Problem Solving"]'::jsonb, '["Python","SDLC Knowledge","Agile"]'::jsonb, '2026-08-20', true),
('Accenture', 'Custom Software Engineer', 'Accenture''s Custom Software Engineer role targets candidates with 0–2 years of experience in full-stack or backend development for client-specific application builds. Engineers work on cloud-native systems, API design, and microservices for clients in banking, insurance, and retail. The role involves Angular or React for frontend and Java or Node.js on the backend, with deployment on AWS or Azure.', 'Bengaluru, India', 'FULL_TIME', 'JUNIOR', '5-8 LPA', 'https://www.accenture.com/in-en/careers', 55, '["Java or Node.js","React or Angular","REST APIs","SQL","Git"]'::jsonb, '["AWS","Docker","Microservices","TypeScript"]'::jsonb, NULL, true),
('Cognizant', 'Programmer Analyst Trainee (GenC)', 'Cognizant''s GenC program is one of India''s largest fresher hiring initiatives, enrolling thousands of engineering graduates each year across a structured 90-day training program in Java, Python, and cloud fundamentals before project allocation. Candidates apply through Cognizant''s campus portal or the SuperSet platform and take a multi-section online assessment. Post-training placement is across BFSI, healthcare, and retail client accounts.', 'Hyderabad, Chennai, Bengaluru, Pune, Mumbai, Kolkata, India', 'FULL_TIME', 'FRESHER', '4-5 LPA', 'https://careers.cognizant.com/global/en/india-fresher-hiring', 40, '["Java or Python","SQL","OOP","Aptitude","SDLC Concepts"]'::jsonb, '["JavaScript","Cloud Basics","DBMS"]'::jsonb, '2026-08-18', true),
('Cognizant', 'Associate – Cloud Infrastructure Engineer (Google Cloud)', 'Cognizant is hiring for the Associate – Google Cloud Infrastructure Engineer role supporting cloud migration, IaC automation, and GCP-based deployments for enterprise clients. Candidates with 0–2 years experience in cloud or DevOps tooling are eligible, and the role involves working with Terraform, Kubernetes, and Cloud Build on GCP. This position falls under Cognizant''s rapidly growing cloud practice.', 'Bengaluru, Hyderabad, India', 'FULL_TIME', 'JUNIOR', '5-9 LPA', 'https://careers.cognizant.com/global/en', 55, '["Google Cloud Platform","Terraform","Kubernetes","Linux","Python"]'::jsonb, '["Docker","Cloud Build","Ansible"]'::jsonb, NULL, true),
('Amazon India', 'Software Development Engineer I (SDE-I)', 'Amazon''s SDE-I University Hiring program recruits fresh engineering graduates and candidates with up to one year of experience into product and platform teams across Bengaluru, Hyderabad, Chennai, and Delhi. Engineers own production systems from day one, participate in code reviews, and work alongside senior engineers on Amazon''s global infrastructure and consumer products. The selection process includes an online assessment and four to five virtual interview rounds focused on DSA, system design, and Amazon leadership principles.', 'Bengaluru, Hyderabad, Chennai, Mumbai, Delhi, India', 'FULL_TIME', 'FRESHER', '22-32 LPA', 'https://amazon.jobs/en/landing_pages/india_sde', 70, '["Data Structures & Algorithms","Java or C++ or Python","System Design Basics","Problem Solving","OOP"]'::jsonb, '["AWS","Distributed Systems","Microservices"]'::jsonb, NULL, true),
('Amazon India', 'Associate – ML Data Operations', 'Amazon is hiring for remote ML Data Operations Associates in India to support data annotation, validation, and quality assurance workflows that feed machine learning model training pipelines. The role is entry-level and accepts fresh graduates with strong attention to detail and basic familiarity with data formats. This work-from-home position is ideal for candidates looking to break into the AI/ML field.', 'Remote, India', 'FULL_TIME', 'FRESHER', '3-5 LPA', 'https://amazon.jobs/en/locations/india', 40, '["Attention to Detail","English Communication","Basic Excel or Sheets","Data Entry","Quality Awareness"]'::jsonb, '["Python Basics","JSON","ML Concepts"]'::jsonb, NULL, true),
('Microsoft India', 'Software Engineer (Entry Level)', 'Microsoft India is hiring entry-level Software Engineers (IC3 equivalent) for its Hyderabad and Bengaluru campuses to work on Azure, Microsoft 365, Teams, Bing, and Copilot products. Fresh 2026 batch graduates and candidates with up to two years of experience are eligible, and the role involves contributing to production code under the guidance of senior engineers. The interview process includes a coding round and a design discussion focused on software fundamentals.', 'Hyderabad, Bengaluru, India', 'FULL_TIME', 'FRESHER', '18-35 LPA', 'https://careers.microsoft.com/v2/global/en/india.html', 70, '["C# or Java or C++","Data Structures & Algorithms","Problem Solving","OOP","System Design Basics"]'::jsonb, '["Azure","TypeScript","Distributed Systems"]'::jsonb, NULL, true),
('Microsoft India', 'Software Engineer II', 'Microsoft''s Software Engineer II (IC4) role in Hyderabad and Bengaluru targets engineers with one to three years of industry experience contributing to cloud-scale distributed systems and AI-powered enterprise products. Responsibilities include designing components, writing clean and testable code, conducting code reviews, and participating in on-call rotations. The India engineering hub ships code that impacts millions of global Microsoft customers.', 'Hyderabad, Bengaluru, India', 'FULL_TIME', 'MID', '25-45 LPA', 'https://careers.microsoft.com/v2/global/en/india.html', 70, '["Java or C# or C++","Distributed Systems","System Design","Code Review","Agile"]'::jsonb, '["Azure","Kubernetes","ML Basics"]'::jsonb, NULL, true),
('Google India', 'Software Engineer, Frontend', 'Google India is hiring Frontend Software Engineers with a minimum of three years of experience in JavaScript, TypeScript, or Dart to work on consumer and enterprise products including Search, Google Workspace, and Maps. The role involves designing and implementing new user-facing features, improving performance and accessibility, and partnering with product managers and UX designers. Candidates go through four to five rounds of technical interviews covering frontend engineering and general software design.', 'Bengaluru, Hyderabad, India', 'FULL_TIME', 'MID', '30-60 LPA', 'https://careers.google.com/locations/india/', 85, '["JavaScript","TypeScript","React or Angular","HTML/CSS","System Design"]'::jsonb, '["Dart/Flutter","Web Performance","Accessibility (WCAG)"]'::jsonb, NULL, true),
('Google India', 'Software Engineer, Machine Learning', 'Google India hires Machine Learning Engineers with experience in designing and implementing distributed ML training and inference systems at scale. The role involves research collaboration, model deployment on Google''s infrastructure, and contributing to Google Brain or the India AI team''s applied projects. Candidates should have practical experience with TensorFlow or JAX and understanding of model evaluation at production scale.', 'Bengaluru, India', 'FULL_TIME', 'MID', '35-70 LPA', 'https://careers.google.com/locations/india/', 85, '["Python","TensorFlow or JAX","ML Algorithms","Distributed Systems","Statistics"]'::jsonb, '["LLM Fine-tuning","MLOps","C++"]'::jsonb, NULL, true),
('Google India', 'Software Engineer, Android', 'Google India is hiring Android Software Engineers with at least two to three years of experience in Kotlin or Java to contribute to Android OS features, Google Play, or consumer Android apps used by billions of users globally. The role involves writing production-grade Android code, conducting code reviews, defining platform APIs, and improving developer tooling. Interviews cover Android-specific system design, data structures, and general programming.', 'Bengaluru, India', 'FULL_TIME', 'MID', '30-60 LPA', 'https://careers.google.com/locations/india/', 85, '["Kotlin","Java","Android SDK","Jetpack Compose","System Design"]'::jsonb, '["Android NDK","Performance Profiling","Accessibility"]'::jsonb, NULL, true),
('Zoho Corporation', 'Software Developer', 'Zoho''s flagship off-campus Software Developer hiring is open across Tamil Nadu cities for fresh engineers and recent graduates who will build features for Zoho''s suite of 55+ SaaS products used by over 100 million users globally. The selection process includes a written aptitude and coding test, multiple technical rounds, and a communication assessment. Zoho is known for a strong engineering culture, internal promotions, and no service bond.', 'Chennai, Coimbatore, Madurai, Salem, Tirunelveli, India', 'FULL_TIME', 'FRESHER', '5.6-8.5 LPA', 'https://careers.zohocorp.com/', 40, '["C or Java","Problem Solving","Data Structures","OOP","Communication"]'::jsonb, '["Linux","DBMS","Open Source Contribution"]'::jsonb, NULL, true),
('Zoho Corporation', 'QA Engineer', 'Zoho is hiring QA Engineers for its ManageEngine and Zoho product lines to design and execute functional, regression, and automation test suites for enterprise IT management software. Fresh graduates and those with up to two years of experience in manual or automation testing are eligible for this role based across Zoho''s Tamil Nadu offices. The process involves a written test, technical rounds on testing concepts, and a communication round.', 'Chennai, Coimbatore, India', 'FULL_TIME', 'FRESHER', '4.5-7 LPA', 'https://careers.zohocorp.com/', 40, '["Manual Testing","Test Case Design","SQL","Bug Reporting","Analytical Thinking"]'::jsonb, '["Selenium","Python","API Testing"]'::jsonb, NULL, true),
('Zoho Corporation', 'Machine Learning Engineer', 'Zoho''s ML Engineering track recruits graduates with strong mathematics and programming foundations to work on Zia — Zoho''s AI assistant — and 25+ Zia Agents embedded across Zoho''s product suite. Engineers build and fine-tune models for NLP, recommendation systems, and business process automation at a scale serving millions of Zoho customers. A separate selection track from the Software Developer path, this role requires demonstrated ML project work or research publications.', 'Chennai, India', 'FULL_TIME', 'FRESHER', '8-14 LPA', 'https://careers.zohocorp.com/', 55, '["Python","Machine Learning","NLP Basics","Statistics","Linear Algebra"]'::jsonb, '["PyTorch","Transformer Models","MLflow"]'::jsonb, NULL, true),
('Freshworks', 'Software Engineer', 'Freshworks Chennai hires Software Engineers for its globally used SaaS products including Freshdesk, Freshservice, and Freshsales, serving over 60,000 customers worldwide. Engineers work in cross-functional squads to ship product features end-to-end, from backend Rails or Node.js services to frontend React components. The hiring bar is high for a fresher product role, requiring strong DSA and system design fundamentals.', 'Chennai, Bengaluru, India', 'FULL_TIME', 'JUNIOR', '12-20 LPA', 'https://careers.freshworks.com/', 55, '["Ruby on Rails or Node.js","React","SQL","DSA","REST APIs"]'::jsonb, '["AWS","Redis","Sidekiq"]'::jsonb, NULL, true),
('Freshworks', 'DevOps / Platform Engineer', 'Freshworks is hiring Platform Engineers to maintain and scale its multi-region SaaS infrastructure that serves enterprise customers with strict availability SLAs. The role involves managing Kubernetes clusters, building CI/CD pipelines, and improving observability using Datadog and OpenTelemetry. Candidates with 0–2 years of DevOps or cloud experience in a SaaS environment are encouraged to apply.', 'Chennai, India', 'FULL_TIME', 'JUNIOR', '10-18 LPA', 'https://careers.freshworks.com/', 55, '["Kubernetes","Docker","CI/CD","Linux","Python or Bash"]'::jsonb, '["Terraform","Datadog","AWS or GCP"]'::jsonb, NULL, true),
('Freshworks', 'QA Automation Engineer', 'Freshworks QA team is hiring automation engineers to build and maintain end-to-end test frameworks for its suite of SaaS products used in customer support, CRM, and ITSM workflows. The role involves writing test automation in Ruby or JavaScript using Selenium and Cypress and integrating tests into CI pipelines. Engineers with 0–2 years of automation experience in a product company are preferred.', 'Chennai, India', 'FULL_TIME', 'JUNIOR', '8-14 LPA', 'https://careers.freshworks.com/', 55, '["Selenium or Cypress","JavaScript or Ruby","REST API Testing","CI/CD","Test Design"]'::jsonb, '["Postman","Jest","Allure Reports"]'::jsonb, NULL, true),
('Razorpay', 'Software Development Engineer I (Backend)', 'Razorpay hires backend SDE-I engineers to work on its payments infrastructure, banking APIs, and merchant platform that processes a large share of India''s digital payments. Engineers build high-throughput, low-latency services in Go, Java, or Ruby on Rails and are expected to own features end-to-end within weeks of joining. The selection involves two to three rounds of DSA and system design interviews plus a culture fit discussion.', 'Bengaluru, India', 'FULL_TIME', 'JUNIOR', '18-28 LPA', 'https://razorpay.com/jobs/', 70, '["Go or Java or Ruby","Distributed Systems","SQL","REST APIs","DSA"]'::jsonb, '["Kafka","Redis","AWS","Payment Systems"]'::jsonb, NULL, true),
('Razorpay', 'Junior Analyst – Risk Management', 'Razorpay is hiring a Junior Analyst in its Risk Management team in Bengaluru to monitor payment transaction patterns, identify fraud signals, and build rule-based and ML-assisted risk models. The role requires strong SQL skills, attention to detail, and the ability to communicate risk findings to product and engineering stakeholders. This is an early-career opportunity ideal for graduates with data analytics or finance backgrounds.', 'Bengaluru, India', 'FULL_TIME', 'FRESHER', '8-14 LPA', 'https://razorpay.com/jobs/', 40, '["SQL","Data Analysis","Excel","Attention to Detail","Communication"]'::jsonb, '["Python","Power BI","Payment Industry Knowledge"]'::jsonb, NULL, true),
('Razorpay', 'Full Stack Developer', 'Razorpay is looking for Full Stack Developers who can build both frontend merchant-facing dashboards in React and backend API services in Go or Node.js for its suite of payment and banking products. The role involves close collaboration with product managers and designers to ship features that improve merchant and end-user payment experiences. Candidates should have shipped at least one production-grade full-stack application.', 'Bengaluru, India', 'FULL_TIME', 'JUNIOR', '16-25 LPA', 'https://razorpay.com/jobs/', 70, '["React","Node.js or Go","SQL","REST APIs","Git"]'::jsonb, '["Redux","TypeScript","Redis"]'::jsonb, NULL, true),
('PhonePe', 'Software Development Engineer I', 'PhonePe hires SDE-I engineers to work on its digital payments platform serving 500 million+ registered users across UPI, insurance, mutual funds, and the PhonePe Switch mini-app store. Engineers join backend, mobile, or data teams and are expected to build reliable, highly concurrent systems that handle peak transaction volumes during festive sales. The interview process involves a coding test and two to three technical rounds.', 'Bengaluru, India', 'FULL_TIME', 'JUNIOR', '16-25 LPA', 'https://www.phonepe.com/careers/', 70, '["Java or Kotlin or Go","DSA","Distributed Systems","SQL","REST APIs"]'::jsonb, '["Kafka","Microservices","AWS"]'::jsonb, NULL, true),
('PhonePe', 'Android Developer', 'PhonePe is hiring Android developers to work on its primary consumer app used daily by hundreds of millions of Indians for payments, insurance, and financial services. The role covers feature development in Kotlin with Jetpack Compose, performance optimization for low-end devices, and maintaining a CI/CD pipeline that deploys to millions of Android users. Candidates with 0–2 years of Android development experience and a strong portfolio of shipped apps are encouraged to apply.', 'Bengaluru, India', 'FULL_TIME', 'JUNIOR', '15-24 LPA', 'https://www.phonepe.com/careers/', 70, '["Kotlin","Android SDK","Jetpack Compose","MVVM","REST APIs"]'::jsonb, '["Coroutines","Hilt","Performance Profiling"]'::jsonb, NULL, true),
('Swiggy', 'Associate Software Development Engineer', 'Swiggy is hiring Associate SDEs (fresh graduates or 0–1 year of experience) to work across its food delivery, Instamart quick commerce, and logistics platforms that handle millions of daily orders. Engineers work on microservices in Java or Go, contribute to real-time data pipelines, and develop features that directly affect restaurant, customer, and delivery-partner experiences. Eligible batches are 2024 and 2025 B.Tech graduates with a strong grounding in DSA.', 'Bengaluru, India', 'FULL_TIME', 'FRESHER', '15-22 LPA', 'https://careers.swiggy.com/', 70, '["Java or Go","DSA","SQL","System Design Basics","OOP"]'::jsonb, '["Kafka","Redis","Kubernetes"]'::jsonb, NULL, true),
('Swiggy', 'Android Developer (SDE-I)', 'Swiggy''s consumer mobile team hires Android engineers to build and maintain the Swiggy and Instamart apps used by millions of daily active users across India. The role covers feature delivery in Kotlin with Jetpack libraries, maintaining low crash rates, improving app startup performance, and working with backend teams on new API contracts. Candidates should have shipped at least one production Android app and be comfortable with asynchronous programming using Coroutines.', 'Bengaluru, India', 'FULL_TIME', 'JUNIOR', '18-30 LPA', 'https://careers.swiggy.com/', 70, '["Kotlin","Android SDK","Coroutines","Jetpack","REST APIs"]'::jsonb, '["Compose","Performance Profiling","A/B Testing"]'::jsonb, NULL, true),
('Swiggy', 'Data Analyst', 'Swiggy''s data team is hiring entry-level Data Analysts to extract business insights from large transaction, logistics, and customer behaviour datasets to inform product and operations decisions. The role involves writing complex SQL queries, building dashboards in Looker or Superset, and presenting findings to business stakeholders across supply chain, marketing, and product teams. Fresh graduates with strong quantitative skills and proficiency in Python and SQL are eligible.', 'Bengaluru, India', 'FULL_TIME', 'FRESHER', '8-15 LPA', 'https://careers.swiggy.com/', 55, '["SQL","Python","Data Visualization","Statistics","Excel"]'::jsonb, '["Looker","Airflow","A/B Testing"]'::jsonb, NULL, true),
('Zomato', 'Software Development Engineer I (Backend)', 'Zomato hires backend SDEs to work on its food delivery and dining-out platform infrastructure that serves millions of restaurant searches, orders, and delivery transactions daily across 800+ Indian cities. Engineers build and maintain high-availability microservices in Go or Java, work on real-time order routing algorithms, and contribute to platform reliability improvements. The Bengaluru engineering hub drives most core product development.', 'Bengaluru, Gurugram, India', 'FULL_TIME', 'JUNIOR', '18-30 LPA', 'https://www.zomato.com/careers', 70, '["Go or Java","Distributed Systems","SQL","DSA","Microservices"]'::jsonb, '["Kafka","Redis","Kubernetes","AWS"]'::jsonb, NULL, true),
('Zomato', 'iOS Developer', 'Zomato is looking for iOS developers to work on the consumer-facing Zomato app, which serves millions of users for food delivery, restaurant discovery, and dining experiences. The role involves building new features in Swift with SwiftUI, maintaining compatibility across iOS versions, and optimising app performance for networks with variable quality. Candidates should have a shipped iOS app in the App Store or demonstrated internship experience.', 'Gurugram, India', 'FULL_TIME', 'JUNIOR', '18-28 LPA', 'https://www.zomato.com/careers', 70, '["Swift","SwiftUI","iOS SDK","REST APIs","MVVM or VIPER"]'::jsonb, '["Core Data","Combine","App Store Review Process"]'::jsonb, NULL, true),
('Zomato', 'Machine Learning Engineer', 'Zomato''s data science team is hiring ML Engineers to build recommendation systems, demand forecasting models, ETA prediction pipelines, and fraud detection systems that directly affect the order experience for millions of users. Engineers work with large-scale Python ML pipelines, deploy models to production using Kubernetes and MLflow, and iterate on model performance using A/B testing frameworks. Candidates with one to two years of ML experience or strong academic projects are encouraged to apply.', 'Bengaluru, Gurugram, India', 'FULL_TIME', 'JUNIOR', '20-35 LPA', 'https://www.zomato.com/careers', 70, '["Python","Machine Learning","SQL","MLflow","Statistics"]'::jsonb, '["Spark","Recommendation Systems","A/B Testing"]'::jsonb, NULL, true),
('Zomato', 'QA Automation Engineer', 'Zomato''s QA team is hiring automation engineers to build test frameworks for its consumer mobile apps (Android and iOS), backend APIs, and payment flows that process millions of daily transactions. The role involves writing automated tests in Python with pytest or Java with TestNG, integrating with CI/CD pipelines, and contributing to a shift-left testing culture across engineering squads. Fresh graduates or candidates with up to two years of QA experience are eligible.', 'Bengaluru, India', 'FULL_TIME', 'JUNIOR', '10-18 LPA', 'https://www.zomato.com/careers', 55, '["Selenium or Appium","Python or Java","API Testing","CI/CD","Test Planning"]'::jsonb, '["Cypress","Allure","Mobile Test Automation"]'::jsonb, NULL, true),
('Meesho', 'Software Development Engineer I', 'Meesho is hiring SDE-Is for its e-commerce platform that enables millions of small sellers and social commerce entrepreneurs across India''s tier-2 and tier-3 cities. Engineers work on backend services, data pipelines, and mobile features that handle catalogue management, order fulfilment, and seller analytics. The engineering culture emphasises ownership, experimentation, and fast iteration in an early-career-friendly environment.', 'Bengaluru, India', 'FULL_TIME', 'JUNIOR', '15-22 LPA', 'https://careers.meesho.com/', 70, '["Java or Python","DSA","SQL","Microservices","REST APIs"]'::jsonb, '["Kafka","Redis","AWS"]'::jsonb, NULL, true),
('Meesho', 'Data Scientist', 'Meesho''s data science team is hiring junior data scientists to work on seller growth models, price recommendation engines, and demand forecasting systems that serve millions of active sellers. The role involves exploratory data analysis in Python, building and validating ML models, and translating model outputs into actionable seller-facing features. Candidates with a quantitative degree or demonstrated ML projects are eligible.', 'Bengaluru, India', 'FULL_TIME', 'JUNIOR', '15-25 LPA', 'https://careers.meesho.com/', 55, '["Python","Machine Learning","SQL","Statistics","Data Analysis"]'::jsonb, '["PySpark","XGBoost","Feature Engineering"]'::jsonb, NULL, true),
('Groww', 'Software Development Engineer I (Backend)', 'Groww is hiring backend engineers for its investment and financial services platform that helps over 10 million Indians invest in stocks, mutual funds, and IPOs. Engineers build low-latency trading systems, financial data APIs, and regulatory compliance services using Java and Go in a microservices architecture. The role requires a solid grasp of concurrency, distributed systems, and financial data integrity.', 'Bengaluru, India', 'FULL_TIME', 'JUNIOR', '18-28 LPA', 'https://groww.in/careers', 70, '["Java or Go","Distributed Systems","SQL","DSA","REST APIs"]'::jsonb, '["Kafka","Redis","SEBI Compliance Basics"]'::jsonb, NULL, true),
('Groww', 'Android Developer', 'Groww is hiring Android developers to build and improve its investing app used by millions of users for real-time stock trading, mutual fund SIPs, and portfolio management. The role involves Kotlin development with Jetpack Compose, deep-linking for trade flows, and real-time chart rendering performance optimization. Candidates should demonstrate strong mobile engineering fundamentals and ideally have experience with financial or high-frequency-update UIs.', 'Bengaluru, India', 'FULL_TIME', 'JUNIOR', '16-26 LPA', 'https://groww.in/careers', 70, '["Kotlin","Jetpack Compose","MVVM","REST APIs","Android SDK"]'::jsonb, '["Coroutines","WebSockets","Charts Libraries"]'::jsonb, NULL, true),
('CRED', 'Software Engineer (Backend)', 'CRED is hiring backend engineers to work on its credit card payments and financial lifestyle platform for India''s premium credit card-using population. Engineers build high-reliability payment and rewards systems in Go or Java, integrate with banks and credit bureaus, and maintain services that process billions of rupees in credit card bill payments monthly. The hiring process is selective and favours candidates who can demonstrate strong fundamentals and prior project impact.', 'Bengaluru, India', 'FULL_TIME', 'JUNIOR', '20-35 LPA', 'https://careers.cred.club/', 70, '["Go or Java","Distributed Systems","SQL","REST APIs","System Design"]'::jsonb, '["Kafka","Redis","Payment Gateway APIs"]'::jsonb, NULL, true),
('CRED', 'Data Scientist', 'CRED''s data team hires data scientists to build credit risk models, personalisation engines, and fraud detection systems for its premium fintech product used by over 12 million verified creditworthy users. The role requires designing experiments, building predictive models using Python and scikit-learn, and collaborating with product managers to translate model outputs into features. Candidates with strong quantitative backgrounds and demonstrable ML project work are preferred.', 'Bengaluru, India', 'FULL_TIME', 'JUNIOR', '18-30 LPA', 'https://careers.cred.club/', 70, '["Python","Machine Learning","SQL","Statistics","Experiment Design"]'::jsonb, '["Credit Risk Models","Feature Engineering","Tableau"]'::jsonb, NULL, true),
('HCLTech', 'Graduate Engineer Trainee', 'HCLTech''s TechBee program offers a structured entry point for fresh engineering graduates across development, testing, cloud, and infrastructure service lines serving global enterprise clients. Trainees undergo domain-specific training before placement on client projects in banking, manufacturing, or telecom verticals. The program is open to 2025 and 2026 engineering graduates across disciplines.', 'Bengaluru, Noida, Chennai, Pune, India', 'FULL_TIME', 'FRESHER', '3.5-5 LPA', 'https://www.hcltech.com/careers', 40, '["Java or Python","SQL","OOP","Aptitude","Communication"]'::jsonb, '["Cloud Basics","Linux","Git"]'::jsonb, NULL, true),
('HCLTech', 'DevOps Engineer – Junior', 'HCLTech is hiring junior DevOps engineers to support cloud infrastructure automation, CI/CD pipeline management, and containerisation projects for global enterprise clients on AWS and Azure. Candidates with 0–2 years of experience in Jenkins, Docker, Kubernetes, or Terraform and a background in Linux administration are eligible. The role involves on-call support rotations and working with cross-functional delivery teams.', 'Bengaluru, India', 'FULL_TIME', 'JUNIOR', '5-10 LPA', 'https://www.hcltech.com/careers', 55, '["Jenkins","Docker","Linux","Shell Scripting","AWS or Azure"]'::jsonb, '["Kubernetes","Terraform","Ansible"]'::jsonb, NULL, true),
('Oracle India', 'Support Engineer 1', 'Oracle India is hiring Support Engineer 1 candidates for its Bengaluru office to provide technical support for Oracle Cloud Infrastructure (OCI), Oracle Database, and enterprise application customers globally. The role involves diagnosing customer issues, writing knowledge-base articles, and collaborating with product engineering teams to resolve critical production defects. Fresh engineering graduates and candidates with up to one year of experience in Java, SQL, or Linux administration are eligible.', 'Bengaluru, India', 'FULL_TIME', 'FRESHER', '6-10 LPA', 'https://careers.oracle.com/jobs/#en/sites/jobsearch/jobs?location=India', 40, '["Java or SQL","Linux","Troubleshooting","Customer Communication","RDBMS"]'::jsonb, '["Oracle Database","Cloud Basics","Python"]'::jsonb, NULL, true),
('Flipkart', 'Software Development Engineer I', 'Flipkart hires SDE-Is through campus placements and its GRiD off-campus competition for engineering teams working on India''s largest e-commerce platform covering catalogue, search, recommendations, supply chain, and quick commerce via Flipkart Minutes. Engineers work with large-scale backend services and are expected to have strong DSA and low-level design skills from day one. The GRiD pathway is explicitly designed to recruit talent from Tier-2 and Tier-3 colleges.', 'Bengaluru, India', 'FULL_TIME', 'FRESHER', '18-28 LPA', 'https://tech.flipkart.com/', 70, '["Java or Python","DSA","Low-Level Design","SQL","System Design Basics"]'::jsonb, '["Kafka","Redis","Competitive Programming"]'::jsonb, NULL, true),
('Flipkart', 'Frontend Engineer', 'Flipkart is hiring Frontend Engineers to work on its web and hybrid mobile interfaces for product discovery, checkout, and seller onboarding experiences used by 350 million+ customers. The role involves React or Next.js development, performance optimisation for low-bandwidth networks, and building reusable component libraries. Engineers collaborate closely with designers and backend teams on end-to-end feature delivery.', 'Bengaluru, India', 'FULL_TIME', 'JUNIOR', '16-26 LPA', 'https://tech.flipkart.com/', 70, '["React","JavaScript","HTML/CSS","TypeScript","Performance Optimization"]'::jsonb, '["Next.js","Webpack","Web Accessibility"]'::jsonb, NULL, true),
('Flipkart', 'ML Engineer', 'Flipkart''s AI/ML team hires ML Engineers to build recommendation systems, search ranking models, catalogue enrichment pipelines, and demand forecasting systems that drive Flipkart''s e-commerce personalization engine. The role requires production-grade ML experience with Python, model training on large datasets, and familiarity with MLOps tooling for experiment tracking and deployment. SDE-1 equivalent fresh hires from campus routes can also enter through the data-science track.', 'Bengaluru, India', 'FULL_TIME', 'JUNIOR', '20-35 LPA', 'https://tech.flipkart.com/', 70, '["Python","Machine Learning","PySpark","SQL","MLflow"]'::jsonb, '["Recommendation Systems","Deep Learning","Feature Stores"]'::jsonb, NULL, true),
('Walmart Global Tech India', 'Software Development Engineer I', 'Walmart Global Tech India''s Bengaluru hub hires SDE-Is for its global retail technology platforms covering e-commerce, supply chain, inventory management, and Sam''s Club membership systems. Engineers work on Java-based distributed systems, cloud-native microservices on GCP and Azure, and open-source frameworks including Apache Spark and Kafka that power Walmart''s massive global retail operation. The role targets fresh campus hires and off-campus candidates with strong DSA skills.', 'Bengaluru, India', 'FULL_TIME', 'FRESHER', '20-30 LPA', 'https://careers.walmart.com/results?locationType=City&locationName=Bengaluru&jobCategory=Technology&subCategory=Software%20Engineering', 70, '["Java","Distributed Systems","SQL","DSA","Microservices"]'::jsonb, '["GCP","Kafka","Spark"]'::jsonb, NULL, true),
('Rippling', 'Software Engineer I – Platform', 'Rippling India is hiring Software Engineers for its Bengaluru office to work on the Rippling workforce management platform that helps companies manage HR, IT, and finance in one unified system. The role involves building scalable platform features in Python and TypeScript, contributing to the GraphQL API layer, and integrating with enterprise software like HRIS and payroll systems. Rippling''s India office is a fast-growing engineering hub with high ownership and direct product impact.', 'Bengaluru, India', 'FULL_TIME', 'JUNIOR', '20-35 LPA', 'https://www.rippling.com/careers', 70, '["Python","TypeScript","GraphQL","SQL","REST APIs"]'::jsonb, '["React","AWS","Enterprise Integrations"]'::jsonb, NULL, true),
('Harman (Samsung Company)', 'Associate Engineer – AI/ML', 'Harman India is hiring Associate Engineers specialising in AI and ML in Python for its Bengaluru office to work on intelligent audio, automotive software, and enterprise IoT solutions. Fresh B.E./B.Tech/M.Tech graduates are eligible and will work on model development, signal processing, and deploying ML models in embedded or cloud environments under senior engineer mentorship. The role bridges software engineering and applied machine learning across Harman''s product lines.', 'Bengaluru, India', 'FULL_TIME', 'FRESHER', '6-12 LPA', 'https://careers.harman.com/', 55, '["Python","Machine Learning","TensorFlow or PyTorch","Signal Processing Basics","DSA"]'::jsonb, '["Edge ML","C++","OpenCV"]'::jsonb, NULL, true),
('Capgemini India', 'Analyst (Fresher) – Application Development', 'Capgemini India''s Analyst (Fresher) role recruits engineering graduates for client-facing application development, digital transformation, and cloud migration projects across Capgemini''s BFSI, energy, and manufacturing clients. The selection process involves Capgemini''s online assessment (InfyTQ-style aptitude plus coding) followed by a technical and HR interview. Trainees undergo a structured 90-day onboarding and skilling program before client placement.', 'Bengaluru, Pune, Hyderabad, Mumbai, India', 'FULL_TIME', 'FRESHER', '4-6 LPA', 'https://www.capgemini.com/in-en/careers/', 40, '["Java or Python","SQL","OOP","Aptitude","Communication"]'::jsonb, '["Cloud Basics","Agile","JavaScript"]'::jsonb, NULL, true),
('Capgemini India', 'DevOps Engineer – Cloud & Infra', 'Capgemini India is hiring junior DevOps engineers for cloud and infrastructure automation projects supporting enterprise clients migrating to AWS and Azure. The role involves setting up CI/CD pipelines using Jenkins and GitLab CI, managing containers with Docker and Kubernetes, and automating infrastructure provisioning with Terraform. Candidates with 0–2 years of cloud engineering or DevOps experience are eligible.', 'Bengaluru, Pune, India', 'FULL_TIME', 'JUNIOR', '5-10 LPA', 'https://www.capgemini.com/in-en/careers/', 55, '["Docker","Kubernetes","Jenkins","Terraform","AWS or Azure"]'::jsonb, '["Ansible","Python","Prometheus"]'::jsonb, NULL, true),
('Wipro', 'Trainee Manual Testing Engineer', 'Wipro is hiring Trainee Manual Testing Engineers for its Gurugram and Noida offices to perform functional, regression, and integration testing on enterprise web and mobile applications for BFSI and retail clients. The role suits 2024 batch B.E./B.Tech graduates who have covered SDLC and STLC concepts and can write detailed test cases and bug reports. Candidates undergo a 30-day internal QA training before client project allocation.', 'Gurugram, Noida, India', 'FULL_TIME', 'FRESHER', '3.5-4.5 LPA', 'https://careers.wipro.com/', 40, '["Manual Testing","SDLC","Test Case Writing","Bug Reporting","SQL Basics"]'::jsonb, '["Selenium Basics","JIRA","Agile"]'::jsonb, NULL, true),
('Infosys BPM', 'Process Executive – Digital', 'Infosys BPM is hiring fresh graduates for digital process roles covering data analytics, RPA, and business process operations for global clients in finance, HR, and procurement. The role involves working with tools like UiPath, Power BI, and Excel to automate and report on business processes and assist in digital transformation engagements. This is an ideal entry point for non-engineering graduates interested in transitioning into a tech-adjacent career.', 'Bengaluru, Pune, Mysore, India', 'FULL_TIME', 'FRESHER', '3-5 LPA', 'https://www.infosysbpm.com/careers.html', 40, '["Excel","Communication","Data Entry","Analytical Thinking","Process Awareness"]'::jsonb, '["Power BI","UiPath Basics","SQL"]'::jsonb, NULL, true),
('Tech Mahindra', 'Associate Software Engineer', 'Tech Mahindra recruits fresh engineering graduates as Associate Software Engineers for its delivery teams working on telecom, IT, and enterprise digital transformation engagements. The role involves Java or Python development, test automation, or cloud support depending on the client project assigned after initial training. The hiring process includes an online assessment followed by a technical interview and HR discussion.', 'Hyderabad, Pune, Noida, Chennai, India', 'FULL_TIME', 'FRESHER', '3.25-5 LPA', 'https://careers.techmahindra.com/', 40, '["Java or Python","SQL","OOP","Communication","Logical Reasoning"]'::jsonb, '["Linux","Cloud Basics","DBMS"]'::jsonb, NULL, true),
